import {getLanguage,onLanguageChange} from './i18n.js';
import {HEIGHT_TEMPLATES,HEIGHT_INTERFACE,HEIGHT_LIMITS,parseHeightAlgorithm} from './bounded-height-controller.js';
import {DEFAULT_LANDING_TASK,LANDING_LIBRARY_KEY,LandingTaskRunner,createLandingFixture,landingPreview,loadLandingLibrary,saveLandingLibrary,parseLandingArchive,bestLanding,validateLandingResult} from './landing-challenge.js';
import {currentExperimentIdentity,contentLabel,captureExperimentSnapshot,attachRuntimeProvenance} from './experiment-records.js';
import {compareConditions} from './research-comparison.js';
import {PersistenceState,writeArchiveCandidate} from './research-storage.js';
const copy=x=>JSON.parse(JSON.stringify(x)),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=(x,n=3)=>Number.isFinite(x)?x.toFixed(n):'—';
const L=(zh,en)=>getLanguage()==='en'?en:zh;
const words={title:['抗扰着陆 · 控制律研究','Disturbed landing · control-law research'],intro:['固定实验室场地，先起飞，再经历定时侧风与可选单喷口降额，最后在半径 1.5 m 区域落稳。控制图只替换高度外环，水平 / 姿态 / 喷口仍由现有物理控制。','Fixed laboratory field: take off, encounter timed crosswind and optional nozzle derating, then settle within a 1.5 m radius. The graph replaces only the height outer loop; horizontal / attitude / nozzle control uses the existing physics.'],supply:['供气模式','Gas supply'],bench:['恒压外供气','Constant-pressure external supply'],finite:['有限车载气源','Finite onboard gas'],pressure:['初始压力 / bar','Initial pressure / bar'],height:['目标世界高度 / m','Target world height / m'],fault:['左前主喷口可用比例','Front-left lift nozzle health'],seed:['观测种子（V1 无噪声）','Observer seed (V1: no noise)'],preview:['任务时序与成功条件','Task timeline and success conditions'],law:['可编辑高度控制图 V1','Editable height control graph V1'],lawHelp:['编辑下方 JSON 树：const / input、add / sub / mul / div / min / max、clamp、integrate、filter。可改变组合；输入 error、height、targetHeight、verticalSpeed、time、dt。4 个有界状态槽，禁止代码、循环及外部访问。','Edit the JSON tree below: const / input, add / sub / mul / div / min / max, clamp, integrate, filter. Change their composition; observations are error, height, targetHeight, verticalSpeed, time and dt. Four bounded state slots; no code, loops or external access.'],pd:['载入 PD 模板','Load PD template'],pi:['载入积分 + 滤波模板','Load integral + filter template'],save:['保存当前控制图','Save current control graph'],saved:['已保存控制图','Saved control graphs'],live:['三维挑战 / 重试','Live challenge / retry'],numeric:['后台同任务研究','Run task numerically'],cancel:['取消 / 交还控制','Cancel / hand over'],history:['任务与算法结果','Task and algorithm results'],compareSaved:['与另一条已保存结果比较','Compare another saved result'],rerun:['所选任务重新决策','Re-execute selected task'],compare:['原算法与编辑算法对照','Compare original and edited laws'],load:['载入所选结果控制图','Load selected result graph'],events:['关键事件遥测回看（不移动现场）','Review event telemetry (live vehicle unchanged)'],export:['完整任务整库 JSON','Full task library JSON'],one:['选中完整结果 JSON','Selected full result JSON'],import:['合并导入任务归档','Merge task archive'],protected:['导出受保护原文','Export protected original'],chart:['高度响应 · m','Height response · m'],professional:['专业指标与比较条件','Metrics and comparison conditions']};
const reasonNames={terminal_capture_failed:['末态不可恢复，最后有效状态与故障描述已保留','Terminal unavailable; last valid state and fault descriptions retained'],stable_landing:['落稳完成','Stable landing completed'],hard_or_tilted_touchdown:['硬着陆 / 接地姿态超限','Hard / tilted touchdown'],premature_contact:['任务着陆前提前接地','Premature ground contact'],takeoff_target_not_reached:['未达到规定起飞高度','Takeoff height not reached'],hull_collision:['车体碰撞','Hull collision'],outside_working_area:['离开工作区','Outside working area'],landing_not_reached:['超时未接地','Timeout before landing'],landing_not_stable_or_outside_target:['未落稳或落在目标外','Not settled or outside target'],controller_fault:['控制图故障已停用','Control graph fault; disabled'],controller_command_rejected:['高度控制请求被拒绝','Height command rejected'],solver_fault:['求解器故障，触发态已保留','Solver fault; trigger state retained'],user_cancel:['用户取消','User cancelled'],pilot_takeover:['驾驶输入接管','Pilot takeover']};
export function createLandingResearchPanel({mount,getSim,getLiveAvailable=()=>true,onRestoreExperiment,onBeforeStart=()=>{},onStart=()=>{},onCancel=()=>{},notify=()=>{},storage}={}){
  const doc=mount.ownerDocument,loaded=loadLandingLibrary(storage),persistence=new PersistenceState(loaded.warning||'',loaded.protectedRaw);let library=loaded.value,selectedId=library.records.at(-1)?.id??null,runner=null,worker=null,job=null,pair=null,disposed=false,serial=0,attempts=library.attempts??[],message='',draftWarning='',draftRaw=null,draftDiskRaw=null,eventCursor=null;
  mount.classList.add('landing-research-panel');mount.setAttribute('data-no-i18n','');
  const label=k=>`<span data-lr-label="${k}"></span>`,button=k=>`<button type="button" data-lr-action="${k}">${label(k)}</button>`;
  mount.innerHTML=`<h3>${label('title')}</h3><p class="rc-help">${label('intro')}</p><p class="rc-live-state" data-lr="authority" role="status"></p><p class="rc-message" data-kind="warning" data-lr="persistence" role="alert" hidden></p><div class="rc-grid"><label class="rc-field">${label('supply')}<select data-lr="supply"><option value="bench" data-lr-label="bench"></option><option value="finite" data-lr-label="finite"></option></select></label><label class="rc-field">${label('pressure')}<input type="number" data-lr="pressure" min="100" max="350" value="350" step="10"></label><label class="rc-field">${label('height')}<input type="number" data-lr="height" min=".8" max="80" value="2.5" step=".1"></label><label class="rc-field">${label('fault')}<input type="number" data-lr="fault" min="0" max="1" value="1" step=".25"></label><label class="rc-field">${label('seed')}<input type="number" data-lr="seed" min="0" max="4294967295" value="31415" step="1"></label></div><details class="rc-section" open><summary>${label('preview')}</summary><pre class="rc-record-details" data-lr="preview"></pre></details><section class="rc-section"><h3>${label('law')}</h3><p class="rc-help">${label('lawHelp')}</p><div class="rc-button-row">${button('pd')}${button('pi')}</div><textarea data-lr="algorithm" aria-label="Height controller JSON AST" rows="18" spellcheck="false"></textarea><p class="rc-help" data-lr="graph-state"></p><div class="rc-button-row">${button('save')}</div><label class="rc-field">${label('saved')}<select data-lr="algorithms"></select></label></section><div class="rc-program-actions">${button('live')}${button('numeric')}</div><div class="rc-numeric-controls"><b data-lr="status" role="status"></b>${button('cancel')}</div><section class="rc-section"><h3>${label('history')}</h3><select data-lr="records"></select><label class="rc-field">${label('compareSaved')}<select data-lr="compare-record"></select></label><p class="rc-live-state" data-lr="verdict"></p><div class="rc-button-row">${button('rerun')}${button('compare')}${button('load')}</div><h4>${label('chart')}</h4><canvas data-lr="chart" width="720" height="260"></canvas><details class="rc-section" open><summary>${label('professional')}</summary><div class="rc-comparison" data-lr="metrics"></div></details><details class="rc-section"><summary>${label('events')}</summary><select data-lr="events"></select><pre data-lr="event-detail" class="rc-record-details"></pre></details><div class="rc-button-row">${button('export')}${button('one')}<label class="rc-file-button">${label('import')}<input type="file" accept=".json,application/json" data-lr="import"></label>${button('protected')}</div></section>`;
  const $=k=>mount.querySelector(`[data-lr="${k}"]`),buttons=k=>[...mount.querySelectorAll(`[data-lr-action="${k}"]`)];
  $('algorithm').value=JSON.stringify(HEIGHT_TEMPLATES.pd,null,2);
  function task(){for(const key of ['pressure','height','fault','seed'])if(!$(key).checkValidity()||!Number.isFinite($(key).valueAsNumber))throw Error(L('任务参数无效：','Invalid task parameter: ')+key);return{...copy(DEFAULT_LANDING_TASK),supplyMode:$('supply').value,initialPressureBar:$('pressure').valueAsNumber,targetHeightM:$('height').valueAsNumber,nozzleScale:$('fault').valueAsNumber,seed:$('seed').valueAsNumber};}
  function selected(){return library.records.find(r=>r.id===selectedId)??null;}
  function download(value,name){const url=URL.createObjectURL(new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type:'application/json'})),a=doc.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function save(candidate=library){candidate={...candidate,attempts};try{saveLandingLibrary(storage,candidate,{protectedRaw:loaded.protectedRaw,expectedRaw:loaded.raw});loaded.raw=storage.getItem(LANDING_LIBRARY_KEY);persistence.saved();paintPersistence();return true;}catch(error){persistence.failed(error,candidate.records.map(r=>r.id));paintPersistence();return false;}}
  function paintPersistence(){const state=persistence.snapshot();$('persistence').hidden=!state.sessionOnly&&!draftWarning;$('persistence').textContent=(state.sessionOnly?L('仅本会话 / 未保存：','Session only / unsaved: ')+state.message+' ':'')+draftWarning+(state.sessionOnly||draftWarning?L('。完整结果与整库可导出；完成不等于已保存。','. Export full results/library; completion does not mean persisted.'):'');$('persistence').dataset.persistence=JSON.stringify(state);buttons('protected').forEach(b=>b.hidden=!loaded.protectedRaw&&!draftRaw);}
  function parseDraft(raw){const value=JSON.parse(raw);if(value?.version!==1)throw Error('Unsupported draft version');parseHeightAlgorithm(JSON.stringify(value.algorithm));landingPreview(value.task);return value;}
  function validateDraft({persist=false}={}){try{const algorithm=parseHeightAlgorithm($('algorithm').value),preview=landingPreview(task());$('preview').textContent=JSON.stringify(preview,null,2);$('graph-state').textContent=`${algorithm.hash} · ${algorithm.controlHz} Hz / 120 Hz · ${algorithm.nodeCount}/${HEIGHT_LIMITS.maxNodes} nodes · ±${algorithm.algorithm.outputLimit} m/s² · ${algorithm.algorithm.slewLimit} m/s³`+(preview.warnings.length?'\n'+preview.warnings.join('\n'):'');$('graph-state').dataset.valid='true';if(persist){try{if(!storage)throw Error('Storage unavailable');if(draftRaw!==null)throw Error('Original draft is quarantined');writeArchiveCandidate(storage,'roadster-landing-draft-v1',{version:1,task:task(),algorithm:algorithm.algorithm},{parse:parseDraft,protectedRaw:draftRaw,expectedRaw:draftDiskRaw,maxBytes:65536});draftDiskRaw=storage.getItem('roadster-landing-draft-v1');draftWarning='';}catch(error){draftWarning=L('编辑稿未保存：','Editor draft not saved: ')+error.message;}paintPersistence();}return{algorithm:algorithm.algorithm,task:task()};}catch(error){$('graph-state').dataset.valid='false';$('graph-state').textContent=L('控制图 / 任务无效：','Invalid graph / task: ')+error.message;throw error;}}
  try{const raw=storage?.getItem('roadster-landing-draft-v1');draftDiskRaw=raw??null;if(raw){draftRaw=raw;const draft=parseDraft(raw);$('algorithm').value=JSON.stringify(draft.algorithm,null,2);for(const [field,key]of [['supply','supplyMode'],['pressure','initialPressureBar'],['height','targetHeightM'],['fault','nozzleScale'],['seed','seed']])$(field).value=draft.task[key];draftRaw=null;}}catch(error){draftWarning=L('旧编辑稿只读隔离：','Original draft quarantined: ')+error.message;}
  function append(result){const values=result?.baseline?[result.baseline,result.candidate].filter(Boolean):[result];values.forEach(validateLandingResult);for(const r of values){attachRuntimeProvenance(r);if(library.records.some(old=>old.id===r.id)){r.id+='-'+(++serial);}library.records.push(r);if(!library.algorithms.some(a=>contentLabel(a)===r.algorithm.hash))library.algorithms.push(copy(r.algorithm.algorithm));selectedId=r.id;}pair=result.baseline&&result.candidate?result:null;save();render();notify(L('任务已结束；物理结果和保存状态分别显示。','Task ended; physical outcome and save status are shown separately.'));}
  function recordAttempt(status,reason){if(!job)return;const value={...job,source:undefined,status,reason:String(reason).slice(0,512),finishedAt:new Date().toISOString()},index=attempts.findIndex(a=>a.id===job.id);if(index>=0)attempts[index]=value;else attempts.push(value);}
  function finishWorker(){worker?.terminate();worker=null;job=null;paintStatus();}
  function failWorker(reason){recordAttempt('failed',reason);save();message=L('执行失败已留证：','Execution failure retained: ')+reason;finishWorker();render();}
  function numeric(action='run'){
    if(worker||runner&&!runner.finished)throw Error(L('先取消当前任务。','Cancel the active task first.'));
    const draft=validateDraft({persist:true}),source=selected();if(action!=='run'&&!source)throw Error(L('先选择完整任务记录。','Select a complete task record first.'));
    const id='landing-job-'+Date.now().toString(36)+'-'+(++serial);job={id,action,identity:currentExperimentIdentity(),algorithm:copy(draft.algorithm),task:copy(action==='run'?draft.task:source.task),sourceId:source?.id??null,startedAt:new Date().toISOString(),lastProgress:null};message='';
    try{const WorkerClass=doc.defaultView?.Worker??globalThis.Worker,createdWorker=new WorkerClass(new URL('./landing-research-worker.js',import.meta.url),{type:'module'});worker=createdWorker;const current=()=>!disposed&&worker===createdWorker&&job?.id===id;createdWorker.onmessage=({data})=>{if(!current()||data?.id!==id)return;try{if(data.type==='progress'){job.lastProgress=data.progress;paintStatus();}else if(data.type==='error'||data.type==='rejected')failWorker(data.error);else if(data.type==='result'){const values=data.result?.baseline?[data.result.baseline,data.result.candidate].filter(Boolean):[data.result];values.forEach(validateLandingResult);recordAttempt('completed','Worker returned a physical task outcome');append(data.result);message=L('后台执行结束，详见任务结局。','Numerical execution ended; see the task outcome.');finishWorker();}}catch(error){if(current())failWorker('Worker result rejected: '+error.message);}};createdWorker.onerror=event=>{if(current())failWorker(event.message||'Worker error');};createdWorker.postMessage({id,action,task:draft.task,algorithm:draft.algorithm,source});paintStatus();}catch(error){failWorker(error.message);}
  }
  function live(){if(!getLiveAvailable()||typeof onRestoreExperiment!=='function')throw Error(L('三维不可用；后台同任务研究仍可运行。','Live graphics unavailable; numerical task research remains available.'));const draft=validateDraft({persist:true});cancel('user_cancel');onBeforeStart();const fixture=createLandingFixture(draft.task),snapshot=captureExperimentSnapshot(fixture,'lab');const restored=onRestoreExperiment({snapshot:snapshot.physical,context:'lab',sceneConfiguration:null,allowVersionMismatch:false});runner=new LandingTaskRunner(restored||getSim(),{task:draft.task,algorithm:draft.algorithm,onFinish:r=>{append(r);paintStatus();}});runner.start();message='';onStart({id:'landing-challenge',name:L('抗扰着陆挑战','Disturbed landing challenge')});paintStatus();}
  function cancel(reason='user_cancel'){let active=false;if(runner&&!runner.finished){runner.finish('cancelled',reason);onCancel(reason);active=true;}if(worker&&job){try{job.cancelRequested=true;worker.postMessage({action:'cancel',id:job.id});message=L('正在停止；等待已执行部分返回。','Stopping; waiting for completed portion.');active=true;}catch(error){failWorker(error.message);}}paintStatus();return active;}
  function paintStatus(){const liveState=runner?.getState(),busy=!!job||!!liveState?.running;$('authority').textContent=liveState?.running?L('控制权：高度控制图；驾驶输入立即接管。','Authority: height graph; pilot input takes over immediately.')+` ${liveState.phase} · ${fmt(liveState.timeS,1)} s`:job?L('后台研究：现场车辆保持当前控制权。','Background research: live vehicle authority is unchanged.'):L('控制权：驾驶者。','Authority: pilot.');$('authority').textContent+=' '+L('场地约束：X ±24 m / Z ±42 m，净高 24.1 m；世界高度与净空分开。','Field limits: X ±24 m / Z ±42 m, clear height 24.1 m; world height and clearance are separate.');$('status').textContent=job?`${job.action} · ${job.lastProgress?.step??0} steps`:liveState?.running?`${liveState.phase} · ${liveState.step} steps`:message||L('就绪 · 同任务重新决策','Ready · same-task re-execution');for(const k of ['live','numeric','rerun','compare'])buttons(k).forEach(b=>b.disabled=busy||k==='live'&&!getLiveAvailable());buttons('cancel').forEach(b=>b.disabled=!busy);}
  function draw(){const g=$('chart').getContext('2d');if(!g)return;const records=pair?[pair.baseline,pair.candidate]:selected()?[selected()]:[],w=720,h=260,LX=55,R=700,T=25,B=225;g.clearRect(0,0,w,h);g.fillStyle='#0b1821';g.fillRect(0,0,w,h);g.font='14px Consolas';const maxTime=Math.max(1,...records.map(r=>r.durationS)),maxH=Math.max(1,...records.flatMap(r=>r.samples.map(s=>s.heightM)));g.strokeStyle='#324b59';g.fillStyle='#b8ced4';for(let i=0;i<5;i++){const y=B-(B-T)*i/4;g.beginPath();g.moveTo(LX,y);g.lineTo(R,y);g.stroke();g.fillText(fmt(maxH*i/4,1),3,y+5);}records.forEach((r,i)=>{g.strokeStyle=['#9edbc9','#e6b87b'][i];g.beginPath();r.samples.forEach((s,j)=>{const x=LX+s.timeS/maxTime*(R-LX),y=B-s.heightM/maxH*(B-T);if(j)g.lineTo(x,y);else g.moveTo(x,y);});g.stroke();});g.fillText('0 s',LX,250);g.fillText(fmt(maxTime,1)+' s',R-65,250);if(eventCursor&&eventCursor.timeS<=maxTime){const x=LX+eventCursor.timeS/maxTime*(R-LX);g.strokeStyle='#f3dcab';g.beginPath();g.moveTo(x,T);g.lineTo(x,B);g.stroke();g.fillText(fmt(eventCursor.timeS,3)+' s',Math.min(x+5,R-90),18);}}
  function showEvent(index){const r=selected(),event=r?.events[index];if(!event)return;eventCursor=event;const nearest=r.samples.reduce((a,b)=>Math.abs(b.timeS-event.timeS)<Math.abs(a.timeS-event.timeS)?b:a,r.samples[0]),control=r.controllerIO.reduce((a,b)=>!a||Math.abs(b.step-event.step)<Math.abs(a.step-event.step)?b:a,null);$('event-detail').textContent=JSON.stringify({event,nearestDisplaySample:nearest,sampleOffsetS:nearest?nearest.timeS-event.timeS:null,nearestControlDecision:control,note:'Event step is exact at 120 Hz. The plotted state is the nearest retained 20 Hz sample; the live vehicle is unchanged.'},null,2);draw();}
  function render(){
    for(const n of mount.querySelectorAll('[data-lr-label]'))n.textContent=L(...words[n.dataset.lrLabel]);paintPersistence();paintStatus();
    const record=selected();$('records').innerHTML=library.records.length?library.records.slice().reverse().map(r=>`<option value="${esc(r.id)}"${r.id===selectedId?' selected':''}>${esc(r.task.name)} · ${esc(r.algorithm.algorithm.name)} · ${r.status} / ${r.supplyMode}</option>`).join(''):`<option>${L('尚无任务结果','No task results yet')}</option>`;
    $('compare-record').innerHTML='<option value="">—</option>'+library.records.filter(r=>r.id!==selectedId).map(r=>`<option value="${esc(r.id)}">${esc(r.task.name)} · ${esc(r.algorithm.algorithm.name)} · ${r.status} / ${r.supplyMode}</option>`).join('');$('compare-record').value=pair?.baseline?.id===selectedId?pair.candidate?.id??'':'';
    const currentGraph=$('algorithm').value,oldSelection=$('algorithms').value;$('algorithms').innerHTML='<option value="">—</option>'+library.algorithms.map((a,i)=>`<option value="${i}">${esc(a.name)} · ${contentLabel(a)}</option>`).join('');$('algorithms').value=oldSelection;
    if(record){const best=bestLanding(library.records,record.task,record.algorithm.hash),reason=reasonNames[record.reason];$('verdict').textContent=(reason?L(...reason):record.reason)+` · ${fmt(record.durationS,3)} s`+(record.status==='completed'&&best?L(' · 本条件个人最好 ',' · Personal best for these conditions ')+fmt(best.durationS,3)+' s':'');
      const compared=pair?[pair.baseline,pair.candidate]:[record],conditions=pair?compareConditions(pair.baseline,pair.candidate):null;
      const rows=[[L('任务结局','Task outcome'),r=>reasonNames[r.reason]?L(...reasonNames[r.reason]):r.reason],[L('落点误差 / m','Landing error / m'),r=>r.summary.landingErrorM],[L('首次接地前垂速 / m/s','Pre-contact vertical speed / m/s'),r=>r.summary.firstContact?.preContactVerticalMps],[L('接地倾角 / °','Contact tilt / °'),r=>r.summary.firstContact?.tiltDeg],[L('最小包络间隙估计 / m','Minimum envelope gap estimate / m'),r=>r.summary.minEnvelopeClearanceM],[L('分配受限时间 / s','Allocation-limited time / s'),r=>r.summary.saturationSeconds],[L('高度 RMSE / m','Height RMSE / m'),r=>r.summary.heightRmseM],[L('稳定着陆时刻 / s','Stable landing / s'),r=>r.summary.stableLandingAtS],[L('末次风变化至落稳 / s（含下降）','Last wind change to stable landing / s (includes descent)'),r=>r.summary.recoveryFromLastDisturbanceS],[L('外供气吞吐量 / kg','External gas throughput / kg'),r=>r.summary.externalSupplyKg],[L('车载排气量 / kg','Onboard discharged gas / kg'),r=>r.summary.onboardDischargedKg]];
      $('metrics').innerHTML=(conditions?`<p class="rc-help">${conditions.controlled?L('受控比较：只改变已声明的算法；先看接触与落稳，再看时间和气量。','Controlled comparison: declared algorithm changes only; judge contact and stable landing before time and gas.'):L('描述性比较：初态、模型、风、供气或任务不一致；不判定哪组更好。','Descriptive comparison: initial state, model, wind, supply or task differ; no better/worse verdict.')}</p><pre class="rc-record-details">${esc(JSON.stringify(conditions,null,2))}</pre>`:'')+'<table><thead><tr><th></th>'+compared.map(r=>`<th>${esc(r.algorithm.algorithm.name)} / ${esc(r.supplyMode)}</th>`).join('')+'</tr></thead><tbody>'+rows.map(([k,value])=>`<tr><th>${esc(k)}</th>${compared.map(r=>{const v=value(r);return`<td>${typeof v==='string'?esc(v):fmt(v)}</td>`;}).join('')}</tr>`).join('')+'</tbody></table>'+`<p class="rc-help">${L('主指标：全部','Metrics: all')} ${record.summary.count} × 120 Hz ${L('物理步；曲线20 Hz，控制决策','physical steps; curves 20 Hz, control decisions')} ${record.algorithm.controlHz} Hz. ${esc(record.identity.modelVersion)} / ${esc(record.identity.modelBuildId.slice(0,12))}</p>`;
      $('events').innerHTML=record.events.map((e,i)=>`<option value="${i}">${fmt(e.timeS,3)} s · ${esc(e.type)}</option>`).join('');$('events').value=String(record.events.length-1);showEvent(record.events.length-1);
    }else{$('verdict').textContent=L('先运行一项任务；失败也会保存。','Run a task; failures are retained too.');$('metrics').replaceChildren();}
    // Locale updates never rebuild or translate the editable algorithm.
    if($('algorithm').value!==currentGraph)$('algorithm').value=currentGraph;draw();
  }
  async function action(name){try{
    if(name==='pd'||name==='pi'){$('algorithm').value=JSON.stringify(name==='pd'?HEIGHT_TEMPLATES.pd:HEIGHT_TEMPLATES.filteredPI,null,2);validateDraft({persist:true});}
    else if(name==='save'){const a=validateDraft({persist:true}).algorithm;if(!library.algorithms.some(x=>contentLabel(x)===contentLabel(a)))library.algorithms.push(a);save();render();}
    else if(name==='live')live();else if(name==='numeric')numeric('run');else if(name==='rerun'||name==='compare')numeric(name);else if(name==='cancel')cancel();
    else if(name==='load'){const r=selected();if(r){$('algorithm').value=JSON.stringify(r.algorithm.algorithm,null,2);validateDraft({persist:true});}}
    else if(name==='export')download({...library,attempts,persistence:persistence.snapshot(),editorText:$('algorithm').value,protectedRaw:loaded.protectedRaw,protectedDraftRaw:draftRaw},'roadster-landing-research.json');
    else if(name==='one'){if(selected())download(selected(),selected().id+'.json');}
    else if(name==='protected')download({library:loaded.protectedRaw,draft:draftRaw},'roadster-landing-protected-raw.json');
  }catch(error){message=L('操作未完成：','Action not completed: ')+error.message;notify(message,'warning');paintStatus();}}
  const click=e=>{const button=e.target.closest('[data-lr-action]');if(button){e.stopPropagation();action(button.dataset.lrAction);}},input=e=>{if(e.target.matches('[data-lr="algorithm"],[data-lr="pressure"],[data-lr="height"],[data-lr="fault"],[data-lr="seed"],[data-lr="supply"]'))try{validateDraft({persist:true});}catch{}},change=e=>{if(e.target===$('records')){selectedId=e.target.value;pair=null;render();}else if(e.target===$('compare-record')){const other=library.records.find(r=>r.id===e.target.value);pair=other?{baseline:selected(),candidate:other}:null;render();}else if(e.target===$('algorithms')&&e.target.value!==''){$('algorithm').value=JSON.stringify(library.algorithms[Number(e.target.value)],null,2);try{validateDraft({persist:true});}catch{}}else if(e.target===$('events'))showEvent(Number(e.target.value));};
  const importFile=async e=>{try{const file=e.target.files?.[0];if(!file)return;if(file.size>12*1024*1024)throw Error('Import exceeds 12 MiB');const incoming=parseLandingArchive(await file.text()),merged=new Map(library.records.map(r=>[r.id,r]));for(const r of incoming.records){const old=merged.get(r.id);if(old&&contentLabel(old)!==contentLabel(r))throw Error('Record ID collision; original remains intact');merged.set(r.id,r);}const mergedAttempts=new Map(attempts.map(a=>[a.id,a]));for(const a of incoming.attempts??[]){const old=mergedAttempts.get(a.id);if(old&&contentLabel(old)!==contentLabel(a))throw Error('Attempt ID collision; original remains intact');mergedAttempts.set(a.id,a);}library.records=[...merged.values()];attempts=[...mergedAttempts.values()];for(const a of incoming.algorithms)if(!library.algorithms.some(x=>contentLabel(x)===contentLabel(a)))library.algorithms.push(a);selectedId=incoming.records.at(-1)?.id??selectedId;save();render();}catch(error){message=error.message;paintStatus();}finally{e.target.value='';}};
  mount.addEventListener('click',click);mount.addEventListener('input',input);mount.addEventListener('change',change);$('import').addEventListener('change',importFile);const off=onLanguageChange(()=>{render();try{validateDraft();}catch{}});try{validateDraft();}catch{}render();
  return{beforeStep(input={}){return runner&&!runner.finished?runner.beforeStep(input):input;},afterStep(t){if(runner&&!runner.finished)runner.afterStep(t);},cancel,onContextChange(){if(runner&&!runner.finished&&runner.sim!==getSim())cancel('pilot_takeover');},update(){paintStatus();},getState:()=>({running:!!runner&&!runner.finished,numericRunning:!!job,recordCount:library.records.length,selectedId,persistence:persistence.snapshot(),live:runner?.getState()??null}),getRecords:()=>copy(library.records),dispose(){if(disposed)return;disposed=true;cancel();if(worker){recordAttempt('cancelled','Panel disposed before Worker returned; terminal state unavailable');save();worker.terminate();worker=null;job=null;}off();mount.removeEventListener('click',click);mount.removeEventListener('input',input);mount.removeEventListener('change',change);$('import').removeEventListener('change',importFile);}};
}
